// Experiments: curated demos from the internal Visual Lab, rebuilt on the 0.9 language. Each one
// has a public source folder (site/experiments/<slug>/), run by the site in an iframe of
// public/embed/experiments/<slug>.<mode>.html (generated by scripts/sync-runtime.mjs). Add an entry here
// and a folder there to publish another; only finished experiments are listed.

import { DISTRIBUTION, repositoryUrl } from '~/lib/config';

/** The repository folder of the experiments, on the default branch. */
const REPO_TREE = repositoryUrl('tree/main/site/experiments/');

/** While the repository is private, Source links say so instead of failing silently (config/distribution.json). */
export const REPOSITORY_PUBLIC = DISTRIBUTION.repository.public;

export interface Experiment {
  slug: string;
  /** Catalogue number, shown as a mono label. */
  no: string;
  title: string;
  description: string;
  /** The Reactive CSS capabilities the stylesheet uses, as tags. */
  tags: string[];
  status: 'published' | 'experimental';
  browsers: { tested: string[]; notVerified: string[] };
  /** One line each, for the index; the detail page uses the long forms. */
  input: { short: string; long: string };
  motion: { short: string; long: string };
  /** What the experiment uses and why, for the detail page. */
  capabilities: { name: string; description: string }[];
  /** Short instructions shown along the bottom of the stage. */
  hint: string;
  /** Repository-relative source folder. */
  sourcePath: string;
}

export const EXPERIMENTS: Experiment[] = [
  {
    slug: 'perihelion',
    no: '001',
    title: 'Perihelion · motion card',
    description: 'A foil collector card: 3D tilt, trailing specular light, parallax layers and a spring return.',
    tags: ['mouse(local)', 'element()', ':on(pointerenter)', 'cycle()', ':changed()', 'event()'],
    status: 'published',
    browsers: { tested: ['Chromium', 'WebKit'], notVerified: ['Firefox'] },
    input: { short: 'Pointer, touch, keyboard', long: 'Pointer and touch tilt the card. Click, tap or Enter changes the edition. The range sets the foil.' },
    motion: { short: 'Tilt stops under reduced motion', long: 'With reduced motion, tilt, parallax and sweeps stop. Light, foil and editions still respond.' },
    capabilities: [
      { name: 'mouse(local)', description: 'The pointer position inside the card drives the tilt and where the light falls.' },
      { name: 'element()', description: 'Reads the card’s own size, so the tilt is the same at every card width.' },
      { name: ':on(pointerenter)', description: 'Entering the card lifts it and brings up the foil. Leaving releases it into its spring return.' },
      { name: 'cycle()', description: 'Each click steps through three editions: Aurora, Gilt, Nocturne.' },
      { name: ':changed()', description: 'A light sweep crosses the card once whenever the edition changes.' },
      { name: 'event()', description: 'The foil range writes its value into the stage’s state, so the foil and glitter follow it.' },
    ],
    hint: 'move over the card · click or Enter to change edition',
    sourcePath: 'site/experiments/perihelion',
  },
];

export const experimentHref = (x: Experiment) => `/experiments/${x.slug}/`;
/** `stage`: the experiment's page, with its caption; `card`: the card alone, for previews. */
export const embedSrc = (x: Experiment, mode: 'stage' | 'card') => `/embed/experiments/${x.slug}.${mode}.html`;
export const sourceUrl = (x: Experiment) => REPO_TREE + x.sourcePath.replace(/^site\/experiments\//, '');
export const FEATURED = EXPERIMENTS[0]!;
